using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
public static class F1Horizon {
 const string E="Assets/Afrer_Seconds/05.Model/Environment/1F/";
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit required");
 foreach(string key in new[]{"Earth","Gravel"}){string path=E+"Textures/FW_Dry"+key+".png";if(!File.Exists(path))File.Copy(E+"Textures/AE_"+key+"_Albedo.png",path);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.alphaSource=TextureImporterAlphaSource.None;imp.alphaIsTransparency=false;imp.wrapMode=TextureWrapMode.Repeat;imp.mipmapEnabled=true;imp.SaveAndReimport();}
 for(int i=0;i<3;i++){var l=AssetDatabase.LoadAssetAtPath<TerrainLayer>(E+"FW_Dry"+i+".terrainlayer");l.diffuseTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(E+"Textures/FW_Dry"+(i==1?"Gravel":"Earth")+".png");l.diffuseRemapMax=i==2?new Vector4(1.3f,1.14f,.9f,1):new Vector4(1.5f,1.37f,1.15f,1);l.smoothness=.02f;EditorUtility.SetDirty(l);}
 var near=GameObject.Find("FW_WildernessTerrain").GetComponent<Terrain>();var nd=near.terrainData;var parent=GameObject.Find("WildernessEnding").transform;if(parent.Find("FW_DistantHorizonTerrain"))throw new Exception("Already built horizon");
 var td=new TerrainData{name="FW_DistantHorizonTerrain",heightmapResolution=1025,alphamapResolution=256,baseMapResolution=1024,size=new Vector3(6144,130,5120)};AssetDatabase.CreateAsset(td,E+"FW_DistantHorizonTerrain.asset");var h=new float[1025,1025];for(int z=0;z<1025;z++)for(int x=0;x<1025;x++){float wx=-3072+x*6,wz=-2560+z*5,cx=Mathf.Clamp(wx,-768,768),cz=Mathf.Clamp(wz,-640,640),dist=Vector2.Distance(new Vector2(wx,wz),new Vector2(cx,cz));float edge=nd.GetInterpolatedHeight((cx+768)/1536,(cz+640)/1280)-6;float hills=7+Mathf.PerlinNoise(wx*.0017f+21,wz*.0017f+39)*25+Mathf.Sin(wx*.004f+wz*.003f)*9;float valley=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(40,250,Mathf.Abs(wz+50)));hills=Mathf.Lerp(hills,3+Mathf.Sin(wx*.005f)*3,valley);h[z,x]=(Mathf.Lerp(edge,hills,Mathf.SmoothStep(0,1,Mathf.Clamp01(dist/180)))+30)/130;}td.SetHeights(0,0,h);var holes=new bool[1024,1024];for(int z=0;z<1024;z++)for(int x=0;x<1024;x++)holes[z,x]=!(x>=384&&x<640&&z>=384&&z<640);td.SetHoles(0,0,holes);td.terrainLayers=nd.terrainLayers;var a=new float[256,256,3];for(int z=0;z<256;z++)for(int x=0;x<256;x++){a[z,x,0]=.55f;a[z,x,1]=.15f;a[z,x,2]=.30f;}td.SetAlphamaps(0,0,a);var go=Terrain.CreateTerrainGameObject(td);go.name=td.name;go.transform.SetParent(parent,false);go.transform.position=new Vector3(-3072,-30,-2560);var terrain=go.GetComponent<Terrain>();terrain.materialTemplate=near.materialTemplate;terrain.drawInstanced=true;terrain.heightmapPixelError=10;terrain.basemapDistance=1000;terrain.allowAutoConnect=false;terrain.Flush();near.Flush();
 int rocks=0;foreach(var f in parent.Find("DryScrubAndStone").GetComponentsInChildren<MeshFilter>()){if(!f.name.StartsWith("FW_WildernessRock"))continue;if(!f.GetComponent<Collider>())f.gameObject.AddComponent<MeshCollider>().sharedMesh=f.sharedMesh;rocks++;}
 foreach(var c in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>(true))){c.farClipPlane=4000;if(PrefabUtility.IsPartOfPrefabInstance(c))PrefabUtility.RecordPrefabInstancePropertyModifications(c);}RenderSettings.fogEndDistance=2500;RenderSettings.fogStartDistance=230;Physics.SyncTransforms();EditorUtility.SetDirty(td);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{distantBackgroundSize=new[]{6144,5120},solidRocks=rocks,dryTextureAlpha="ignored at import; original texture files retained"};}
}
